import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    orders_info = {}  # id -> {'side','price','qty','active'}
    arrival_counter = [0]

    def get_arrival():
        arrival_counter[0] += 1
        return arrival_counter[0]

    def match_incoming(side, price, qty, incoming_id):
        # returns remaining qty after matching
        remaining = qty
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_arrival, top_id = heap[0]
            else:
                neg_price, top_arrival, top_id = heap[0]
                top_price = -neg_price

            info = orders_info.get(top_id)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue

            # check price condition
            if price is not None:
                if side == 'buy':
                    if top_price > price:
                        break
                else:
                    if top_price < price:
                        break

            # match
            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                buy_id = incoming_id
                sell_id = top_id
            else:
                buy_id = top_id
                sell_id = incoming_id

            trades.append([buy_id, sell_id, top_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            heapq.heappop(heap)
            if info['qty'] > 0:
                if side == 'buy':
                    heapq.heappush(heap, (top_price, top_arrival, top_id))
                else:
                    heapq.heappush(heap, (-top_price, top_arrival, top_id))
            else:
                info['active'] = False

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            if remaining > 0:
                arrival = get_arrival()
                orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid)
            orders_info[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}

        elif typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False

    return trades

